final_files.rules.py:
class Rule:
    def __init__(self, treats=False):
        self.treats = treats


def should_apply(rule):
    return rule.treats

final_files.test_bug.py:
from rules import Rule, should_apply


def test_enabled():
    assert should_apply(Rule(treats=True)) is True


def test_disabled():
    assert should_apply(Rule(treats=False)) is False
